-- Merged verses in the songbook "Песнь Возрождения 3300" split again (2026-10-25): the number of the
-- next verse was scanned as the letter "З" (or a digit) and glued to its first line, so two verses
-- showed as one; the labels skip that number, so the new verse gets the missing one.
-- Each fix is skipped when that piece of the hymn was changed since.
UPDATE Songs SET song_text = replace(song_text, '' || char(10) || 'З Где,', '' || char(10) || '' || char(10) || 'Куплет 3.' || char(10) || 'Где,') WHERE songbook_id = (SELECT id FROM Songbooks WHERE name = 'Песнь Возрождения 3300') AND number = 3024 AND instr(song_text, '' || char(10) || 'З Где,') > 0;
